const $=id=>document.getElementById(id);let keys={left:false,right:false},soundOn=false,audio=null,toastTimer=0,lastMode='',previousHelp='title',lastFocus=null,damageNumbers=[];
const labelMap=new Map(),worldLabels=new Map();
