function initAudio(){if(!audio)try{audio=new(window.AudioContext||window.webkitAudioContext)();}catch{}if(audio?.state==='suspended')audio.resume().catch(()=>{});}
function tone(freq,duration,shape='sine',volume=.03,end=0){if(!soundOn||!audio)return;let o=audio.createOscillator(),g=audio.createGain();o.type=shape;o.frequency.setValueAtTime(freq,audio.currentTime);if(end)o.frequency.exponentialRampToValueAtTime(Math.max(20,end),audio.currentTime+duration);g.gain.setValueAtTime(volume,audio.currentTime);g.gain.exponentialRampToValueAtTime(.0001,audio.currentTime+duration);o.connect(g).connect(audio.destination);o.start();o.stop(audio.currentTime+duration);}
function noise(duration=.12,volume=.05){if(!soundOn||!audio)return;const b=audio.createBuffer(1,Math.ceil(audio.sampleRate*duration),audio.sampleRate),a=b.getChannelData(0);for(let i=0;i<a.length;i++)a[i]=(Math.random()*2-1)*(1-i/a.length);let s=audio.createBufferSource(),g=audio.createGain(),f=audio.createBiquadFilter();s.buffer=b;f.type='lowpass';f.frequency.value=1500;g.gain.value=volume;s.connect(f).connect(g).connect(audio.destination);s.start();}
function toast(t,d=3){$('toast').textContent=t;$('toast').classList.add('show');toastTimer=d;}
function mode(m){keys.left=keys.right=keys.up=keys.down=false;if(m==='playing')game.resume();else game.pause(m);renderOverlay();}
function begin(){if(!assetsReady)return;initAudio();soundOn=true;$('sound').innerHTML=svg('sound');$('sound').setAttribute('aria-label','关闭声音');game.start();renderOverlay();toast('A / D 移动 · E 与人偶交谈 · M 查看路线与怪物',6);}
function restart(){game.respawn();renderOverlay();toast('余烬重燃',2);}
function help(){previousHelp=game.mode;keys.left=keys.right=keys.up=keys.down=false;if(game.mode==='title')game.mode='help';else if(game.mode==='playing')game.pause('help');else game.mode='help';renderOverlay();}
function closeOverlay(){if(game.mode==='help'){game.mode=previousHelp==='help'?'paused':previousHelp;renderOverlay();}else{game.resume();renderOverlay();}}
function inventory(){if(game.mode==='inventory')closeOverlay();else if(game.mode==='playing'){mode('inventory');}}
function timeText(t){return Math.floor(t/60).toString().padStart(2,'0')+':'+Math.floor(t%60).toString().padStart(2,'0');}
function runStats(){return `<div class="run-stats"><div><b>${game.kills}</b><span>击败敌人</span></div><div><b>${timeText(game.time)}</b><span>本次用时</span></div><div><b>${game.gold}</b><span>收集金币</span></div></div>`;}
function roman(n){return ['','I','II','III','IV','V'][n]||String(n);}
function gearCard(id,gear,label,button){const w=WEAPONS[id],r=RARITIES[gear.rarity],st=STATS[weaponStat(id)];return `<article class="inventory-weapon ${game.p.weapon===id?'active':''}" style="--weapon-color:${w.color}"><div class="gear-label">${label}</div><span class="weapon-symbol">${sym(id)}</span><h3>${w.name} <small>${roman(gear.level||1)}${gear.rarity===2?' ++':gear.rarity===1?' +':''}</small></h3><span class="tag" style="color:${st.color}">${r.name} / ${st.name} / ${w.tag}</span><div class="stat-line"><span>单次伤害 <b>${game.gearDamage(id,gear)}</b></span><span>距离 <b>${w.range}</b></span></div><p>${w.desc}</p><div class="affix">${gear.affix?AFFIXES[gear.affix].name+' · '+AFFIXES[gear.affix].desc:'无额外词缀'}</div><div class="crit">暴击：${w.crit}</div>${button}</article>`;}
